// trace-context.mjs
// 使用 AsyncLocalStorage 实现请求级上下文（traceId / 计时 / 并发隔离）
import { AsyncLocalStorage } from "node:async_hooks";
// Deno 同样可用：import { AsyncLocalStorage } from "node:async_hooks";

// 1. 创建一个上下文容器，泛型上通常存 { traceId, userId?, startedAt }
const als = new AsyncLocalStorage();

// 2. 在任意深度读取上下文，无需传参
export function getTraceId() {
  return als.getStore()?.traceId ?? "unknown";
}

export function logger(msg) {
  console.log(`[${getTraceId()}] ${msg}`);
}

// 3. 模拟一个耗时的异步调用链（Service 层）
async function queryUser(id) {
  logger(`query user ${id}`);
  await new Promise((r) => setTimeout(r, 30)); // 模拟 DB IO
  return { id, name: "Alice" };
}

// 4. 模拟并发上报（互不干扰）
async function reportToApm() {
  await new Promise((r) => setTimeout(r, 10));
  logger("send metrics to APM");
}

async function writeAuditLog() {
  logger("write audit log");
}

// 5. 请求入口：用 als.run 建立上下文作用域
async function handleRequest(reqId) {
  const traceId = `trace-${reqId}`;
  return als.run({ traceId, startedAt: Date.now() }, async () => {
    logger("request start");

    const user = await queryUser(reqId);

    // 并行任务各自继承上下文，不会串号
    await Promise.all([writeAuditLog(), reportToApm()]);

    const cost = Date.now() - als.getStore().startedAt;
    logger(`request done in ${cost}ms, user=${user.name}`);
    return user;
  });
}

// 6. 并发处理两个请求，验证上下文隔离
await Promise.all([handleRequest(1), handleRequest(2)]);

/*
预期输出（顺序可能交错，但 traceId 一定正确配对）：
[trace-1] request start
[trace-2] request start
[trace-1] query user 1
[trace-2] query user 2
[trace-1] write audit log
[trace-2] write audit log
[trace-1] send metrics to APM
[trace-2] send metrics to APM
[trace-1] request done in ~31ms, user=Alice
[trace-2] request done in ~31ms, user=Alice
*/

